+std::ostream& operator<<(std::ostream& os,
+                         ElementsTransitionWithMultipleSources transition) {
+  os << "transition from (";
+  bool first = true;
+  for (MapRef source : transition.sources()) {
+    if (!first) {
+      os << ", ";
+    }
+    first = false;
+    os << Brief(*source.object());
+  }
+  os << ") to " << Brief(*transition.target().object());
+  return os;
+}
